package zone.moddev.mc.ironagearchitecture.roof;

import java.util.*;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.item.ItemStack;
import net.minecraft.util.*;
import net.minecraft.util.math.*;
import net.minecraft.world.World;
import zone.moddev.mc.ironagearchitecture.block.*;

/** Adapts the existing hollow gutter kit to planned fascia faces without another block family. */
public final class RoofGutters {
    private RoofGutters(){}
    public static RoofMeshes.Mesh mesh(RoofPart p){List<RoofMeshes.Face> faces=new ArrayList<>();List<AxisAlignedBB> boxes=new ArrayList<>();double dx=p.data[0]/32.0,dy=p.data[1]/32.0,dz=p.data[2]/32.0;DrainMesh.Face add=(a,b,c,d)->{List<double[]> points=new ArrayList<>();for(double[] v:new double[][]{a,b,c,d}){double[] q=RoofGeometry.rotate(v[0]/16,v[1]/16,v[2]/16,p.facing);points.add(new double[]{q[0]+dx,q[1]+dy,q[2]+dz});}RoofWindowGeometry.add(faces,points,0);};DrainMesh.gutter(p.material==2,p.data[3],add);for(AxisAlignedBB b:DrainGeometry.gutterBoxes(p.material==2,p.data[3],p.facing))clipBox(boxes,b.offset(dx,dy,dz));if(p.material==2&&p.data[5]>0){double[][] path={{0,DrainGeometry.OUTER},{-p.data[5]*.5,DrainGeometry.OUTER}};DrainMesh.pipe(path,add);double[] center=RoofGeometry.rotate(.5,0,DrainGeometry.OUTER/16,p.facing);double radius=DrainGeometry.RADIUS/16;clipBox(boxes,new AxisAlignedBB(center[0]+dx-radius,dy-p.data[5]/32.0,center[2]+dz-radius,center[0]+dx+radius,dy,center[2]+dz+radius));}return faces.isEmpty()?RoofMeshes.EMPTY:new RoofMeshes.Mesh(faces,boxes);}
    private static void clipBox(List<AxisAlignedBB> out,AxisAlignedBB b){double x=Math.max(0,b.minX),y=Math.max(0,b.minY),z=Math.max(0,b.minZ),xx=Math.min(1,b.maxX),yy=Math.min(1,b.maxY),zz=Math.min(1,b.maxZ);if(xx>x+1e-9&&yy>y+1e-9&&zz>z+1e-9)out.add(new AxisAlignedBB(x,y,z,xx,yy,zz));}
    public static boolean fit(World world,BlockPos at,EntityPlayer player,ItemStack stack,EnumFacing clicked,boolean outlet){RoofCell cell=RoofData.get(world).at(world,at);if(cell==null||!cell.designed)return false;RoofPart board=RoofDesignInteraction.target(world,at,player);if(board==null||board.kind!=RoofPart.FASCIA||clicked!=board.facing)return false;if(world.isRemote)return true;RoofPlan plan=RoofData.get(world).interaction(cell.plan,at);if(plan==null||RoofConstruction.busy(world,cell.plan))return false;String id="gutter:"+board.id;Map<Long,RoofCell> all=RoofData.get(world).owned(world,plan);for(RoofCell c:all.values())for(RoofPart p:c.parts)if(p.id.equals(id))return false;
        // The lower fragment owns a board which crosses a vertical cell boundary.
        for(int i=0;i<board.data.length;i+=8)if(board.data[i+4]<0)return false;
        RoofMeshes.Mesh bm=RoofMeshes.get(new RoofCell(cell.plan,at,Collections.singletonList(board),Collections.emptyList()),0);AxisAlignedBB bounds=bm.bounds;EnumFacing facing=board.facing.getOpposite();double[] nominal=RoofGeometry.rotate(.5,0,.8125,facing);double actual=board.facing==EnumFacing.NORTH?bounds.minZ:board.facing==EnumFacing.SOUTH?bounds.maxZ:board.facing==EnumFacing.WEST?bounds.minX:bounds.maxX;double delta=actual-(board.facing.getAxis()==EnumFacing.Axis.X?nominal[0]:nominal[2]),dx=board.facing.getAxis()==EnumFacing.Axis.X?delta:0,dz=board.facing.getAxis()==EnumFacing.Axis.Z?delta:0,dy=bounds.minY;double depth=14.5+(dx*board.facing.getFrontOffsetX()+dz*board.facing.getFrontOffsetZ())*16;int lane=Math.abs(depth-14.5)<.01?2:Math.abs(depth-6.5)<.01?1:Math.abs(depth-1.5)<.01?0:-1;if(lane<0)return false;
        Map<Long,RoofCell> updates=new TreeMap<>();for(int y=0;y<3;y++){BlockPos p=at.up(y);int[] data={RoofAssembly.q(dx),RoofAssembly.q(dy-y),RoofAssembly.q(dz),3,lane,RoofAssembly.q(dy),0,0};RoofPart part=new RoofPart(id,at,RoofPart.GUTTER,outlet?2:1,data,facing);RoofMeshes.Mesh gm=mesh(part);if(gm.faces.isEmpty())continue;if(!world.isBlockLoaded(p))return false;RoofCell current=all.get(p.toLong());if(current==null&&!world.isAirBlock(p))return false;if(!world.isBlockModifiable(player,p)||!player.canPlayerEdit(p,clicked,stack))return false;for(AxisAlignedBB b:gm.boxes)if(!world.checkNoEntityCollision(b.offset(p)))return false;List<RoofPart> parts=new ArrayList<>(current==null?Collections.emptyList():current.parts);parts.add(part);updates.put(p.toLong(),new RoofCell(cell.plan,p,parts,current==null?Collections.emptyList():current.windows));}
        if(updates.isEmpty())return false;RoofConstruction.changing=true;try{for(Map.Entry<Long,RoofCell> e:updates.entrySet())RoofDesignInteraction.write(world,BlockPos.fromLong(e.getKey()),e.getValue());}finally{RoofConstruction.changing=false;}if(!player.capabilities.isCreativeMode){stack.stackSize--;if(stack.stackSize==0){if(player.getHeldItemMainhand()==stack)player.setHeldItem(EnumHand.MAIN_HAND,null);else if(player.getHeldItemOffhand()==stack)player.setHeldItem(EnumHand.OFF_HAND,null);}}refreshCaps(world,plan);return true;
    }
    public static RoofPart outlet(World world,BlockPos at){RoofCell c=RoofData.get(world).at(world,at);if(c!=null&&c.designed)for(RoofPart p:c.parts)if(p.kind==RoofPart.GUTTER&&p.material==2&&p.root.equals(at))return p;return null;}
    public static boolean line(World world,BlockPos at,EntityPlayer player,ItemStack stack,EnumFacing side){if(side!=EnumFacing.DOWN)return false;RoofCell c=RoofData.get(world).at(world,at);if(c==null||!c.designed)return false;RoofPart board=null;for(RoofPart p:c.parts){if(p.kind==RoofPart.SOFFIT)return false;if(p.kind==RoofPart.FASCIA)board=p;}if(board==null)return false;if(world.isRemote)return true;RoofPlan plan=RoofData.get(world).interaction(c.plan,at);if(plan==null||RoofConstruction.busy(world,c.plan)||!world.isBlockModifiable(player,at)||!player.canPlayerEdit(at,side,stack))return false;AxisAlignedBB b=RoofMeshes.get(new RoofCell(c.plan,at,Collections.singletonList(board),Collections.emptyList()),0).bounds;double x=0,xx=1,z=0,zz=1;if(board.facing==EnumFacing.NORTH)z=b.maxZ;if(board.facing==EnumFacing.SOUTH)zz=b.minZ;if(board.facing==EnumFacing.WEST)x=b.maxX;if(board.facing==EnumFacing.EAST)xx=b.minX;if(xx<=x||zz<=z)return false;int[] data={RoofAssembly.q(x),RoofAssembly.q(xx),RoofAssembly.q(z),RoofAssembly.q(zz),RoofAssembly.q(b.minY),RoofAssembly.q(b.minY),2,0};RoofPart lining=new RoofPart("lining:"+board.id,at,RoofPart.SOFFIT,6,data,board.facing);List<RoofPart> parts=new ArrayList<>(c.parts);parts.add(lining);RoofCell next=new RoofCell(c.plan,c.owner,parts,c.windows);for(AxisAlignedBB box:RoofMeshes.get(new RoofCell(c.plan,at,Collections.singletonList(lining),Collections.emptyList()),0).boxes)if(!world.checkNoEntityCollision(box.offset(at)))return false;RoofConstruction.changing=true;try{RoofDesignInteraction.write(world,at,next);}finally{RoofConstruction.changing=false;}if(!player.capabilities.isCreativeMode)stack.stackSize--;return true;}
    public static BlockPos inlet(World world,BlockPos root){RoofPart part=outlet(world,root);return part==null?null:root.up((int)Math.floor(part.data[5]/32.0+.27));}
    public static void refreshCaps(World w,RoofPlan plan){Map<Long,RoofCell> all=RoofData.get(w).owned(w,plan);Map<BlockPos,RoofPart> roots=new HashMap<>();for(Map.Entry<Long,RoofCell> e:all.entrySet())for(RoofPart p:e.getValue().parts)if(p.kind==RoofPart.GUTTER&&p.root.toLong()==e.getKey())roots.put(p.root,p);Map<String,Integer> caps=new HashMap<>();for(RoofPart p:roots.values()){int ends=0;for(int i=0;i<2;i++){RoofPart other=roots.get(p.root.offset(i==0?p.facing.rotateYCCW():p.facing.rotateY()));if(other==null||other.facing!=p.facing||other.data[4]!=p.data[4]||other.data[5]!=p.data[5])ends|=1<<i;}caps.put(p.id,ends);}for(Map.Entry<Long,RoofCell> e:all.entrySet()){boolean changed=false;List<RoofPart> parts=new ArrayList<>();for(RoofPart p:e.getValue().parts){Integer ends=caps.get(p.id);if(ends!=null&&p.data[3]!=ends){int[] a=p.data.clone();a[3]=ends;parts.add(new RoofPart(p.id,p.root,p.kind,p.material,a,p.facing));changed=true;}else parts.add(p);}if(changed)RoofData.get(w).put(w,BlockPos.fromLong(e.getKey()),new RoofCell(e.getValue().plan,e.getValue().owner,parts,e.getValue().windows));}}
}
